public static long findKthSmallest(int N, int M, long K) {
    long low = 1, high = Long.MAX_VALUE;
    while (low < high) {
        long mid = low + (high - low) / 2;
        long count = (mid / N) + (mid / M) - 2 * (mid / lcm(N, M));
        if (count < K) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return low;
}

private static long gcd(long a, long b) {
    while (b != 0) {
        long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

private static long lcm(long a, long b) {
    return a / gcd(a, b) * b;
}
